export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

files.hooks/messages.ts:
// Messages between sessions (Claude Code's SendMessage across sessions on this machine), kept beside
// the snapshot so the board can show them as conversations (increment 015 in the agent-switchboard
// repository). Pure: the hooks in `register.ts` call these.

import { isRecord } from './guards'

/** How many messages, sent and received together, the file keeps. */
export const MAX_MESSAGES = 200

/** Each message's text is capped here, its end kept, as a turn's is. */
export const MAX_MESSAGE_CHARS = 16 * 1024

export type Message = {
  at: string
  direction: 'out' | 'in'
  /** The recipient's name for a sent message; the sender's, from the envelope, for a received one. */
  peer?: string
  text: string
}

/** The engine's envelope around a message from another session, as the model reads it; found anywhere in the text. */
const ENVELOPE = /<cross-session-message\b([^>]*)>([\s\S]*?)<\/cross-session-message>/
const FROM_NAME = /\bfrom-name="([^"]*)"/
const FROM_ADDRESS = /\bfrom="([^"]*)"/

/**
 * A received delivery's sender and body: the envelope's `from-name`, its `from` address (what a reply is
 * sent to) and its contents, when it has one; else the whole text with no sender.
 */
export function receivedOf(text: string): { peer?: string; address?: string; text: string } {
  const envelope = ENVELOPE.exec(text)
  if (!envelope) return { text: text.trim() }
  const attributes = envelope[1] ?? ''
  const peer = FROM_NAME.exec(attributes)?.[1]
  const address = FROM_ADDRESS.exec(attributes)?.[1]
  return { ...(peer ? { peer } : {}), ...(address ? { address } : {}), text: (envelope[2] ?? '').trim() }
}

/** The file with one more message, oldest first, the last `MAX_MESSAGES` kept; a broken file starts afresh. */
export function withMessage(existing: string | undefined, message: Message): string {
  let messages: unknown = []
  try {
    messages = existing === undefined ? [] : JSON.parse(existing)
  } catch {
    messages = []
  }
  const kept = Array.isArray(messages) ? messages.filter(m => isRecord(m) && typeof m.at === 'string' && typeof m.text === 'string') : []
  const { text } = message
  const capped = text.length <= MAX_MESSAGE_CHARS ? text : `…${text.slice(text.length - MAX_MESSAGE_CHARS + 1)}`
  return JSON.stringify([...kept, { ...message, text: capped }].slice(-MAX_MESSAGES))
}

files.hooks/prompt.ts:
// Answering a prompt from the board (agent-switchboard decision 0009): what the mod sends the hub about
// an open prompt, and what the hub's answer does to the call. Pure; `register.ts` does the sending.

import { isRecord } from './guards'

export interface PromptQuestion {
  question: string
  header?: string
  kind: 'choice' | 'text' | 'number'
  options: string[]
  multiSelect: boolean
}

/** The hub's `POST /api/prompts` body. */
export interface BoardPrompt {
  id: string
  sessionId: string
  kind: 'permission' | 'question'
  tool: string
  description?: string
  /** What the call would act on, as the board prints it. */
  input?: string
  questions?: PromptQuestion[]
  openedAt: number
}

export type Outcome = { deny: string } | { allow: true } | { result: Record<string, unknown> }

const RESERVED = ['tool', 'tool_use_id', 'agentId', 'consent']
const QUESTION_KINDS: Record<string, PromptQuestion['kind']> = { choice: 'choice', text: 'text', number: 'number' }

export function promptOf(sessionId: string, id: string, tool: string, args: unknown, openedAt: number): BoardPrompt {
  const input = isRecord(args) ? args : {}
  if (tool === 'AskUserQuestion') {
    const questions = Array.isArray(input.questions) ? input.questions.flatMap(q => questionOf(q) ?? []) : []
    return { id, sessionId, kind: 'question', tool, questions, openedAt }
  }
  const prompt: BoardPrompt = { id, sessionId, kind: 'permission', tool, input: inputText(tool, input), openedAt }
  if (typeof input.description === 'string') prompt.description = input.description
  return prompt
}

function questionOf(value: unknown): PromptQuestion | undefined {
  if (!isRecord(value) || typeof value.question !== 'string') return undefined
  const options = Array.isArray(value.options) ? value.options.flatMap(o => (isRecord(o) && typeof o.label === 'string' ? [o.label] : [])) : []
  const question: PromptQuestion = {
    question: value.question,
    kind: (typeof value.kind === 'string' && QUESTION_KINDS[value.kind]) || 'choice',
    options,
    multiSelect: value.multiSelect === true,
  }
  if (typeof value.header === 'string') question.header = value.header
  return question
}

/** What the terminal shows a call would act on: the command, an edit's lines, a file's content. */
function inputText(tool: string, input: Record<string, unknown>): string {
  const { command, file_path: path, old_string: before, new_string: after, content } = input
  if (tool === 'Bash' && typeof command === 'string') return command
  if (tool === 'Edit' && typeof path === 'string' && typeof before === 'string' && typeof after === 'string') {
    const removed = before.split('\n').map(line => `- ${line}`)
    const added = after.split('\n').map(line => `+ ${line}`)
    return [path, '', ...removed, ...added].join('\n')
  }
  if (tool === 'Write' && typeof path === 'string' && typeof content === 'string') return `${path}\n\n${content}`
  const own = Object.fromEntries(Object.entries(input).filter(([key]) => !RESERVED.includes(key)))
  return JSON.stringify(own, null, 2)
}

/** The hub's answer as the call's outcome, or `undefined` when it is no answer this call can take. */
export function outcomeOf(answerText: string, tool: string, args: unknown): Outcome | undefined {
  let answer: unknown
  try {
    answer = JSON.parse(answerText)
  } catch {
    return undefined
  }
  if (!isRecord(answer)) return undefined
  if (tool === 'AskUserQuestion') {
    if (!isRecord(answer.answers)) return undefined
    const questions = isRecord(args) ? args.questions : undefined
    const result: Record<string, unknown> = { questions, answers: answer.answers }
    if (typeof answer.response === 'string') result.response = answer.response
    return { result }
  }
  if (answer.decision === 'allow') return { allow: true }
  if (answer.decision !== 'deny') return undefined
  const note = typeof answer.note === 'string' ? answer.note.trim() : ''
  return { deny: note ? `Denied from Agent Switchboard: ${note}` : 'Denied from Agent Switchboard.' }
}

/** A call by its tool and its own arguments, keys sorted: a re-run and its permission check compare equal. */
export function callKey(tool: string, args: unknown): string {
  const own = Object.entries(isRecord(args) ? args : {})
    .filter(([key]) => !RESERVED.includes(key))
    .sort(([a], [b]) => a.localeCompare(b))
  return JSON.stringify([tool, own])
}

/** A call's own arguments, without the keys the engine reserves, to run it again. */
export function ownArgs(args: unknown): Record<string, unknown> {
  return Object.fromEntries(Object.entries(isRecord(args) ? args : {}).filter(([key]) => !RESERVED.includes(key)))
}

/**
 * A board prompt that is one of the session's slash commands, as the person would type it in the
 * terminal (`/reload-plugins`, `/compact keep the plan`): the command and its arguments. Anything else,
 * an unknown name included, is a prompt for the model.
 */
export function slashCommandOf(text: string, known: readonly string[]): { command: string; args: string } | undefined {
  const typed = /^\/(\S+)(?:\s+([\s\S]*))?$/.exec(text.trim())
  const name = typed?.[1]?.toLowerCase()
  // `$.command.list()` gives names only, no aliases; capitals typed are forgiven, as the typeahead does.
  const command = name === undefined ? undefined : known.find(k => k.toLowerCase() === name)
  if (command === undefined) return undefined
  return { command, args: (typed?.[2] ?? '').trim() }
}

files.hooks/settings.ts:
// What this mod takes from the board's `settings.json`: how long a permission check answered `ask`
// stays undecided before it counts as a prompt waiting on the human, and whether the board may queue
// prompts for the session. The hub validates the file with the same rules and defaults; a value the hub
// would refuse is ignored here.

import { isRecord } from './guards'

export const DEFAULT_PROMPT_DELAY_MS = 10_000

/** The `board` section of the settings file, or nothing when the file is missing or broken. */
function boardOf(settingsText: string | undefined): Record<string, unknown> | undefined {
  if (settingsText === undefined) return undefined
  try {
    const parsed: unknown = JSON.parse(settingsText)
    return isRecord(parsed) && isRecord(parsed.board) ? parsed.board : undefined
  } catch {
    return undefined
  }
}

export function promptDelayMsOf(settingsText: string | undefined): number {
  const seconds = boardOf(settingsText)?.promptDelaySeconds
  return typeof seconds === 'number' && Number.isInteger(seconds) && seconds >= 0 && seconds <= 120 ? seconds * 1000 : DEFAULT_PROMPT_DELAY_MS
}

/** Whether the board may queue prompts for this session (decision 0010): only when exactly on; off by default. */
export function promptingAllowedOf(settingsText: string | undefined): boolean {
  return boardOf(settingsText)?.allowPrompting === true
}

files.hooks/snapshot.ts:
// The snapshot file, format version 1, as Agent Switchboard's hub reads it:
// `docs/reference/snapshot-format.md` in the agent-switchboard repository is the contract. Every field
// is bounded, so a file stays small however long the session runs. `tool` marks the file as this mod's;
// the hub reads omp's own files only for snapshots without it.

import { isRecord } from './guards'
import type { SessionState } from './state'

export const SNAPSHOT_FORMAT_VERSION = 1

/** Character limits for free text, including the ellipsis that marks a cut. */
export const LIMITS = { question: 300, todoCurrent: 120, path: 1024, id: 128, lastSaid: 400 } as const

export interface Snapshot {
  formatVersion: typeof SNAPSHOT_FORMAT_VERSION
  tool: 'claude-code'
  sessionId: string
  cwd: string
  agentDir: string
  pid: number
  /** When the session began, when known. */
  startedAt?: string
  state: 'idle' | 'running' | 'waiting'
  lastActivityAt: string
  heartbeatAt: string
  openAsk?: { question: string; count: number; since: string }
  todo?: { closed: number; total: number; current?: string }
  cost: number
  /** The end of the session's latest answer: where its conclusion is. */
  lastSaid?: { text: string; at: string }
  /** What the session's latest tool call is doing, at most 80 characters; kept while idle. */
  activity?: { text: string; at: string }
  endedAt?: string
  endReason?: string
}

export function toSnapshot(state: SessionState): Snapshot {
  const [oldest] = state.waiting
  const snapshot: Snapshot = {
    formatVersion: SNAPSHOT_FORMAT_VERSION,
    tool: 'claude-code',
    sessionId: cut(state.sessionId, LIMITS.id),
    cwd: cut(state.cwd, LIMITS.path),
    agentDir: cut(state.agentDir, LIMITS.path),
    pid: state.pid,
    state: oldest ? 'waiting' : state.phase,
    lastActivityAt: iso(state.lastActivityAt),
    heartbeatAt: iso(state.heartbeatAt),
    cost: state.cost,
  }
  if (state.startedAt !== undefined) snapshot.startedAt = iso(state.startedAt)
  if (oldest) snapshot.openAsk = { question: cut(oldest.question, LIMITS.question), count: oldest.count, since: iso(oldest.since) }
  if (state.todo) {
    const todo: NonNullable<Snapshot['todo']> = { closed: state.todo.closed, total: state.todo.total }
    if (state.todo.current !== undefined) todo.current = cut(state.todo.current, LIMITS.todoCurrent)
    snapshot.todo = todo
  }
  if (state.lastSaid) {
    const { text } = state.lastSaid
    const tail = text.length <= LIMITS.lastSaid ? text : `…${text.slice(text.length - LIMITS.lastSaid + 1)}`
    snapshot.lastSaid = { text: tail, at: iso(state.lastSaid.at) }
  }
  if (state.activity) snapshot.activity = { text: state.activity.text, at: iso(state.activity.at) }
  if (state.ended) {
    snapshot.endedAt = iso(state.ended.at)
    snapshot.endReason = cut(state.ended.reason, LIMITS.id)
  }
  return snapshot
}

type Env = { SWITCHBOARD_HOME?: string; CLAUDE_CONFIG_DIR?: string; USERPROFILE?: string; HOME?: string }

/** The board's data folder: `SWITCHBOARD_HOME`, else `.agent-switchboard` in the home folder; none without a home. */
export function boardHomeOf(env: Env): string | undefined {
  if (env.SWITCHBOARD_HOME) return env.SWITCHBOARD_HOME
  const home = env.USERPROFILE ?? env.HOME
  return home ? join(home, '.agent-switchboard') : undefined
}

/** Claude Code's configuration folder, reported as the snapshot's `agentDir`; the hub never reads it. */
export function agentDirOf(env: Env): string {
  if (env.CLAUDE_CONFIG_DIR) return env.CLAUDE_CONFIG_DIR
  const home = env.USERPROFILE ?? env.HOME
  return home ? join(home, '.claude') : ''
}

/** A session id becomes a file name, so it must not be able to name anything else. */
const SAFE_ID = /^[A-Za-z0-9][A-Za-z0-9._-]*$/

/** The full last answer beside the snapshot is capped here, its end kept: the conclusion is there. */
export const MAX_SAID_CHARS = 64 * 1024

/** Where the full last answer goes, for the project page: `said/<sessionId>.md` in the board folder. */
export function saidPathOf(boardHome: string, sessionId: string): string | undefined {
  if (!SAFE_ID.test(sessionId) || sessionId.includes('..')) return undefined
  return join(boardHome, 'said', `${sessionId}.md`)
}

export function saidTextOf(text: string): string {
  return text.length <= MAX_SAID_CHARS ? text : `…${text.slice(text.length - MAX_SAID_CHARS + 1)}`
}

/** How many turns the history beside the snapshot keeps (increment 011). */
export const MAX_TURNS = 50

/**
 * Each turn's answer is capped here, its end kept (increment 014): 16 K characters each; 50 turns are
 * about 0.8 MB of mostly ASCII text, up to roughly 2.5 MB in the worst case.
 */
export const MAX_TURN_CHARS = 16 * 1024

/** A turn for the history: the session's last answer in full up to the cap, not the snapshot's tail. */
export function turnOf(state: SessionState): { at: string; text: string } | undefined {
  if (!state.lastSaid) return undefined
  const { text, at } = state.lastSaid
  return { at: iso(at), text: text.length <= MAX_TURN_CHARS ? text : `…${text.slice(text.length - MAX_TURN_CHARS + 1)}` }
}

/** Where a session's turn history goes: `said/<sessionId>.turns.json` in the board folder. */
export function turnsPathOf(boardHome: string, sessionId: string): string | undefined {
  if (!SAFE_ID.test(sessionId) || sessionId.includes('..')) return undefined
  return join(boardHome, 'said', `${sessionId}.turns.json`)
}

/** The history with one more turn, oldest first, the last `MAX_TURNS` kept; a missing or broken file starts afresh. */
export function withTurn(existing: string | undefined, turn: { at: string; text: string }): string {
  let turns: unknown = []
  try {
    turns = existing === undefined ? [] : JSON.parse(existing)
  } catch {
    turns = []
  }
  const kept = Array.isArray(turns) ? turns.filter(t => isRecord(t) && typeof t.at === 'string' && typeof t.text === 'string') : []
  return JSON.stringify([...kept, turn].slice(-MAX_TURNS))
}

/** Where a session's messages with other sessions go: `said/<sessionId>.messages.json` (increment 015). */
export function messagesPathOf(boardHome: string, sessionId: string): string | undefined {
  if (!SAFE_ID.test(sessionId) || sessionId.includes('..')) return undefined
  return join(boardHome, 'said', `${sessionId}.messages.json`)
}

/** Where the files a session's tools edit go: `said/<sessionId>.edits.json` (increment 019). */
export function editsPathOf(boardHome: string, sessionId: string): string | undefined {
  if (!SAFE_ID.test(sessionId) || sessionId.includes('..')) return undefined
  return join(boardHome, 'said', `${sessionId}.edits.json`)
}

/** The board's settings file, which the hub owns; this mod only reads it. */
export function settingsPathOf(boardHome: string): string {
  return join(boardHome, 'settings.json')
}

export function snapshotPathOf(boardHome: string, sessionId: string): string | undefined {
  if (!SAFE_ID.test(sessionId) || sessionId.includes('..')) return undefined
  return join(boardHome, 'sessions', `${sessionId}.json`)
}

/** Joins with the separator the base already uses, so a Windows home stays a Windows path. */
function join(base: string, ...parts: string[]): string {
  const sep = /^[A-Za-z]:\\/.test(base) || (base.includes('\\') && !base.includes('/')) ? '\\' : '/'
  return [base.replace(/[\\/]+$/, ''), ...parts].join(sep)
}

function cut(text: string, limit: number): string {
  return text.length <= limit ? text : `${text.slice(0, limit - 1)}…`
}

function iso(epochMs: number): string {
  return new Date(epochMs).toISOString()
}

